create or replace function public.gfauto_manager_bulk_assign_social_leads(p_lead_ids uuid[], p_target_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_role text; v_target_role text; v_count integer; begin select role into v_role from profiles where id=v_actor; select role into v_target_role from profiles where id=p_target_id; if v_role<>'manager' or v_target_role<>'sales' then raise exception 'not authorized'; end if; if coalesce(array_length(p_lead_ids,1),0)=0 or array_length(p_lead_ids,1)>100 then raise exception 'invalid batch size'; end if; update social_leads set assigned_to=p_target_id, assignment_target_role='sales', manager_id=v_actor, assigned_by=v_actor, assigned_at=now(), status='assigned', metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('assignment_mode','manager_bulk'), updated_at=now() where id=any(p_lead_ids) and manager_id=v_actor and assigned_to=v_actor and status not in ('converted','invalid'); get diagnostics v_count=row_count; return v_count; end $$; grant execute on function public.gfauto_manager_bulk_assign_social_leads(uuid[],uuid) to authenticated;

create or replace function public.gfauto_social_lead_funnel(p_from timestamptz default null,p_to timestamptz default null) returns table(sales_id uuid,sales_name text,assigned_count bigint,urgent_count bigint,responded_count bigint,response_within_3m_count bigint,contacted_count bigint,hot_count bigint,valid_count bigint,long_term_count bigint,invalid_count bigint,crm_converted_count bigint,signed_count bigint) language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_role text; begin select role into v_role from profiles where id=v_actor; if v_role not in ('owner','manager') then raise exception 'not authorized'; end if; return query select p.id,p.full_name,count(l.id),count(l.id) filter(where l.sla_due_at is not null),count(l.id) filter(where l.response_started_at is not null),count(l.id) filter(where l.response_started_at is not null and l.sla_due_at is not null and l.response_started_at<=l.sla_due_at),count(l.id) filter(where l.contact_attempted_at is not null or l.response_started_at is not null),count(l.id) filter(where l.lead_quality='hot'),count(l.id) filter(where l.lead_quality='valid'),count(l.id) filter(where l.lead_quality='long_term'),count(l.id) filter(where l.lead_quality='invalid'),count(l.id) filter(where l.converted_at is not null or l.converted_customer_id is not null),count(l.id) filter(where c.signed_at is not null) from profiles p left join social_leads l on l.assigned_to=p.id and (p_from is null or l.assigned_at>=p_from) and (p_to is null or l.assigned_at<p_to) left join customers c on c.id=l.converted_customer_id where p.role='sales' and p.active=true and (v_role='owner' or exists(select 1 from social_leads lm where lm.assigned_to=p.id and lm.manager_id=v_actor)) group by p.id,p.full_name order by count(l.id) desc,p.full_name; end $$; grant execute on function public.gfauto_social_lead_funnel(timestamptz,timestamptz) to authenticated;